INSERT INTO `wp_comments` VALUES
(1,1,'Un comentarista de WordPress','wapuu@wordpress.example','https://es.wordpress.org/','','2026-10-13 16:31:14','2026-10-13 14:31:14','Hola, esto es un comentario.\nPara empezar a moderar, editar y borrar comentarios, por favor, visita en el escritorio la pantalla de comentarios.\nLos avatares de los comentaristas provienen de <a href=\"https://es.gravatar.com/\">Gravatar</a>.',0,'post-trashed','','comment',0,0);
